ids = env['stock.lot']._serial_duplicate_lot_ids()
if ids:
    action = {
        'type': 'ir.actions.act_window',
        'name': env._('Duplicate Serial Numbers'),
        'res_model': 'stock.lot',
        'view_mode': 'list,form',
        'domain': [('id', 'in', ids)],
        'context': {'create': False},
    }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': env._('Serial Number Duplicate Audit'),
            'message': env._('No duplicate serial numbers found.'),
            'type': 'success',
            'sticky': False,
        },
    }
